```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

/// Key within the `subscriptions` store holding the newline-separated feed URLs.
const SUBSCRIPTIONS_KEY: &str = "urls";

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let urls = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

export!(Node);
